() => {
  window.__pdfErrors = [];
  const origError = console.error;
  console.error = function(...args) {
    window.__pdfErrors.push(args.map(a => {
      try {
        if (a instanceof Error) return a.message + ' | ' + (a.stack || '').split('\n').slice(0,5).join(' ; ');
        return typeof a === 'object' ? JSON.stringify(a).slice(0, 500) : String(a);
      } catch(e) { return String(a); }
    }).join(' || '));
    origError.apply(console, args);
  };
  window.addEventListener('unhandledrejection', (e) => {
    window.__pdfErrors.push('UNHANDLED_REJECTION: ' + (e.reason && e.reason.message ? e.reason.message : String(e.reason)));
  });
  return 'hooked';
}

async () => {
  await new Promise(r => setTimeout(r, 6000));
  return {
    errors: window.__pdfErrors || [],
    overlayCount: document.querySelectorAll('.fixed.inset-0').length,
    bodyOverflow: document.body.style.overflow
  };
}

