() => {
  const report = document.querySelector('main .border.rounded-3xl') || document.body;
  const els = report.querySelectorAll('*');
  let oklchCount = 0;
  const samples = [];
  for (const el of els) {
    const c = window.getComputedStyle(el);
    for (const prop of ['color', 'background-color', 'border-color']) {
      const v = c.getPropertyValue(prop);
      if (v && v.includes('oklch')) {
        oklchCount++;
        if (samples.length < 5) samples.push({tag: el.tagName, cls: (el.className||'').toString().slice(0,60), prop, value: v});
      }
    }
  }
  // 检查内联样式是否被写入了 oklch（修复的实际效果）
  const inlineOklch = [];
  for (const el of els) {
    if (el.style && (el.style.color.includes('oklch') || el.style.backgroundColor.includes('oklch'))) {
      if (inlineOklch.length < 3) inlineOklch.push({tag: el.tagName, inlineColor: el.style.color.slice(0,50), inlineBg: el.style.backgroundColor.slice(0,50)});
    }
  }
  return { oklchCount, samples, inlineOklch, totalEls: els.length };
}

() => {
  const overlays = document.querySelectorAll('.html2pdf__overlay, .html2pdf__container');
  const fixedOverlays = Array.from(document.querySelectorAll('div')).filter(d => {
    const s = window.getComputedStyle(d);
    return s.position === 'fixed' && s.inset === '0px' && parseFloat(s.opacity) > 0 && s.pointerEvents !== 'none' && s.zIndex > 10;
  }).map(d => ({cls: (d.className||'').toString().slice(0,80), z: window.getComputedStyle(d).zIndex}));
  return { html2pdfResidual: overlays.length, fixedOverlays, bodyOverflow: document.body.style.overflow, pointerEvents: window.getComputedStyle(document.body).pointerEvents };
}

() => {
  return {
    capturedErrors: window.__pdfErrors || [],
    html2pdfResidualNow: document.querySelectorAll('.html2pdf__overlay, .html2pdf__container').length,
    bodyOverflow: document.body.style.overflow
  };
}
